-- 2026-10-31h: MP Background timelines for the next 25 most viewed MPs, batch 8 (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (389 entries, copied exactly from "background-batch8.json", which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 172, 221, 410, 4457, 4484, 4603, 4608, 4645, 4783, 4785, 4979, 5085, 5089, 5105, 5108, 5186, 5197, 5209, 5290, 5302, 5314, 5315, 5328, 5330, 5344,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Every source link was checked by Cowork
-- before the data file was written.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-10-31h-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 121 existing timelines are unchanged (md5);
-- MPs with a timeline go from 121 to 146; each array equals the file exactly; 2108 entries in all afterwards.
-- Undo: 2026-10-31h-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (172, 221, 410, 4457, 4484, 4603, 4608, 4645, 4783, 4785, 4979, 5085, 5089, 5105, 5108, 5186, 5197, 5209, 5290, 5302, 5314, 5315, 5328, 5330, 5344)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (172, 221, 410, 4457, 4484, 4603, 4608, 4645, 4783, 4785, 4979, 5085, 5089, 5105, 5108, 5186, 5197, 5209, 5290, 5302, 5314, 5315, 5328, 5330, 5344) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 121 THEN RAISE EXCEPTION 'expected 121 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
