UPDATE public.mp_biography b SET background_timeline = n.tl, background_last_checked = DATE '2026-10-31'
  FROM bt_new n WHERE b.member_id = n.member_id AND b.background_timeline IS NULL;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  existing_changed integer;
  matching integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (172, 221, 410, 4457, 4484, 4603, 4608, 4645, 4783, 4785, 4979, 5085, 5089, 5105, 5108, 5186, 5197, 5209, 5290, 5302, 5314, 5315, 5328, 5330, 5344) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO existing_changed FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE o.had AND md5(coalesce(b.background_timeline::text, '')) IS DISTINCT FROM o.th;
  SELECT count(*) INTO matching FROM public.mp_biography b JOIN bt_new n USING (member_id)
   WHERE b.background_timeline = n.tl AND jsonb_array_length(b.background_timeline) = n.n AND b.background_last_checked = DATE '2026-10-31';
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT sum(jsonb_array_length(background_timeline)) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'rows changed %, outside the 25 %, existing timelines changed %, rows matching the file %, MPs with a timeline %, entries %',
    changed, changed_outside, existing_changed, matching, with_timeline, entry_total;
  IF changed <> 25 THEN RAISE EXCEPTION 'expected exactly 25 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 25 changed', changed_outside; END IF;
  IF existing_changed <> 0 THEN RAISE EXCEPTION '% of the 121 existing timelines changed', existing_changed; END IF;
  IF matching <> 25 THEN RAISE EXCEPTION 'expected 25 rows matching the file, got %', matching; END IF;
  IF with_timeline <> 146 THEN RAISE EXCEPTION 'expected 146 MPs with a timeline after, got %', with_timeline; END IF;
  IF entry_total <> 2108 THEN RAISE EXCEPTION 'expected 2108 entries, got %', entry_total; END IF;
END $$;

COMMIT;
